"""Independent literal float and Decimal recurrences plus real production loss-first handcase."""
exec(compile('"""Independent literal reconstruction. Does not import production or its input rows.\nReads final scalar outputs ONLY to compare the independently calculated answer.\n"""\nimport json\nfrom pathlib import Path\n\ndef calculate(n,roc,w,k,minor,recovery):\n cash=618.72631865;debt=1169.92258050;parent_cash=308.40323749;parent_debt=810.27716245\n f=[];floor=300.;first5=[]\n for t in range(1,12):\n  n0=n*(1.06**min(t-1,4))*(1.035**min(max(t-5,0),5))*(1.02**max(t-10,0))\n  growth=.06 if t<5 else .035 if t<10 else .02\n  add=floor*.02;floor+=add\n  inv=n0*growth/roc\n  extra=max(0.,([60.,60.,54.594,0.,0.][t-1] if t<=5 else 0.)-.7*inv)\n  flow=n0-inv-extra-([40.,20.,0.,0.,0.][t-1] if t<=5 else 0.)-add\n  f.append(flow)\n  if t<=5:\n   cash+=(42.97696372 if t==1 else 0.)+flow+add-debt*.035*.85-80.-[12.,12.,12.,10.,6.18226376][t-1]-[6.,7.,8.,9.,10.][t-1]-[60.,70.,80.,90.,100.][t-1]\n   debt-=80.;first5.append(cash)\n   parent_cash+=(42.97696372 if t==1 else 0.)+250*1.04**(t-1)-parent_debt*.035-35*1.03**(t-1)-80-60-[60.,70.,80.,90.,100.][t-1]\n   parent_debt-=60\n tail=f[10]/(w-.02)\n ev5=sum(f[t-1]/((1+w)**(t-5)) for t in range(6,11))+tail/(1+w)**5\n excess=cash-300*1.02**5\n pe=min(excess,max(0.,parent_cash-150))\n delayed=sum(1/(1+k)**i for i in range(1,6))/5\n cash_value=pe+(excess-pe)*delayed\n tv=(ev5+cash_value+162.53484360*recovery/(1+k)**3-debt-minor*1.03**5)/193.437735\n v=sum(x/193.437735/(1+k)**t for t,x in enumerate([60.,70.,80.,90.,100.],1))+tv/(1+k)**5\n return {\'primary\':v,\'terminal5\':tv,\'cash5\':cash}\n\nout=json.loads(Path(__file__).parent.joinpath(\'2026-Q3-output.json\').read_text())\nchecks={}\nfor name,args in {\'core_low\':(337.5375,.13,.105,.12,300.,.75),\'base\':(352.5375,.14,.10,.115,280.,.8),\'roic_10pct\':(352.5375,.10,.10,.115,280.,.8)}.items():\n a=calculate(*args);b=out[\'scenarios\'][name]\n assert abs(a[\'primary\']-b[\'primary_holder_dcf_per_share\'])<1e-8\n assert abs(a[\'terminal5\']-b[\'terminal_equity_per_share_year5\'])<1e-8\n assert abs(a[\'cash5\']-b[\'funding_rows\'][-1][\'group_cash\'])<1e-8\n checks[name]=a\nPath(__file__).with_name(\'independent-results.json\').write_text(json.dumps(checks,indent=2)+\'\\n\')\nprint(json.dumps(checks,indent=2))\n', __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
exec(compile("from decimal import Decimal as D,getcontext\nfrom pathlib import Path\nimport json,importlib.util,copy\ngetcontext().prec=40\nF=lambda x:D(str(x))\nroot=Path(__file__).resolve().parent; actual=json.loads((root/'2026-Q3-output.json').read_text())\n\ndef run(n,roi,w,k,minor,recover,struct=False):\n n,roi,w,k,minor,recover=map(F,(n,roi,w,k,minor,recover));g1=F(.03 if struct else .06);g2=F(.02 if struct else .035);g=F(.02)\n debt=F(1169.92258050);cash=F(618.72631865);pc=F(308.40323749);pd=F(810.27716245);legal=F(1319.13549610);reserve=F(96.70158750);floor=F(300);fcf=[];cashrows=[];divs=[]\n for year in range(1,12):\n  if year>1:n*=1+(g1 if year<=5 else g2 if year<=10 else g)\n  ng=g1 if year<5 else g2 if year<10 else g\n  invest=n*ng/roi;project=F([60,60,54.594,0,0][year-1] if year<=5 else 0);extra=max(D(0),project-invest*F(.7));add=floor*F(.02);floor+=add\n  fc=n-invest-extra-F([40,20,0,0,0][year-1]if year<=5 else 0)-add;fcf.append(fc)\n  if year>5:continue\n  dep=F(42.97696372 if year==1 else 0);rate=F(.045 if struct else .035);repay=F(60 if struct else 80);p_repay=F(40 if struct else 60);other=F([12,12,12,10,6.18226376][year-1]);nd=F(3 if struct else year+5)\n  cp=cash+dep+fc+add-debt*rate*F(.85)-repay-other-nd\n  pp=F(190 if struct else 250)*F(1.04)**(year-1);oper=F(185 if struct else 250)*F(1.04)**(year-1)\n  pp_cash=pc+dep+oper-pd*rate-F(35)*F(1.03)**(year-1)-F(95 if struct else 80)-p_repay\n  allocated=min(max(D(0),pp-max(D(0),-legal))*F(.1),max(D(0),F(193.437735)*F(.5)-reserve));reserve+=allocated;legal+=pp-allocated\n  planned=F([40,40,45,50,55][year-1]if struct else year*10+50)\n  dividend=min(planned,max(D(0),min(cp-floor,pp_cash-F(150),legal)));cash=cp-dividend;pc=pp_cash-dividend;legal-=dividend;pd-=p_repay;debt-=repay;divs.append(dividend)\n  cashrows.append([cash,pc,legal,reserve,debt,dividend])\n ev5=sum(fcf[i]/(1+w)**(i-4)for i in range(5,10))+fcf[10]/(w-g)/(1+w)**5\n excess=cash-F(300)*F(1.02)**5;pe=min(excess,max(D(0),pc-F(150)));delayed=sum(1/(1+k)**i for i in range(1,6))/5\n tv=(ev5+pe+(excess-pe)*delayed+F(162.5348436)*recover/(1+k)**3-debt-minor*F(1.03)**5)/F(193.437735)\n value=sum(d/F(193.437735)/(1+k)**i for i,d in enumerate(divs,1))+tv/(1+k)**5\n return value,tv,cashrows\n\nres={}\nfor label,args in {'base':(352.5375,.14,.10,.115,280,.8),'core_low':(337.5375,.13,.105,.12,300,.75),'core_high':(367.5375,.15,.095,.11,260,.85),'roic_10pct':(352.5375,.10,.10,.115,280,.8),'structural_failure':(264.403125,.09,.10,.115,220,.8,True)}.items():\n value,tv,rows=run(*args);a=actual['scenarios'][label];diffs=[abs(float(value)-a['primary_holder_dcf_per_share']),abs(float(tv)-a['terminal_equity_per_share_year5'])]\n for r,t in zip(rows,a['funding_rows']):\n  for v,key in zip(r,['group_cash','parent_cash_budget','parent_legal_retained_budget','parent_statutory_reserve_balance','debt','common_dividend']):diffs.append(abs(float(v)-t[key]))\n assert max(diffs)<1e-8,(label,max(diffs));res[label]={'value':str(value),'TV5':str(tv),'checks':len(diffs),'max_error':max(diffs)}\n# A loss-absorption case is injected into the actual production valuation chain.\nspec=importlib.util.spec_from_file_location('eyebright',root/'2026-Q3.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)\noriginal=m.FACTS['parent_h1_retained'];m.FACTS['parent_h1_retained']=-20\np=copy.deepcopy(m.BASE);p['parent_profit']=10;p['parent_growth']=0\nv=m.value(p);assert v['funding_rows'][0]['parent_statutory_reserve']==0;assert v['funding_rows'][0]['parent_legal_retained_budget']==-10;assert v['funding_rows'][0]['common_dividend']==0\nassert v['funding_rows'][1]['parent_statutory_reserve']==0;assert abs(v['funding_rows'][2]['parent_statutory_reserve']-.01728)<1e-8\nm.FACTS['parent_h1_retained']=original\nres['production_loss_first_cap_case']='passed; first two years reserve zero, subsequent capped 0.01728 million; first dividend zero'\nPath(__file__).with_suffix('.json').write_text(json.dumps(res,ensure_ascii=False,indent=2)+'\\n');print(json.dumps(res,ensure_ascii=False,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
